    case 'minutes':
    case 'minute':
    case 'mins':
    case 'min':
    case 'm':
      return { divisor: m, short: 'm', longSingular: 'minute' };
    case 'seconds':
    case 'second':
    case 'secs':
    case 'sec':
    case 's':
