const s = 1000;
const m = s * 60;
const h = m * 60;
const d = h * 24;
const w = d * 7;
const y = d * 365.25;
const mo = y / 12;

type Years = 'years' | 'year' | 'yrs' | 'yr' | 'y';
type Months = 'months' | 'month' | 'mo';
type Weeks = 'weeks' | 'week' | 'w';
type Days = 'days' | 'day' | 'd';
type Hours = 'hours' | 'hour' | 'hrs' | 'hr' | 'h';
type Minutes = 'minutes' | 'minute' | 'mins' | 'min' | 'm';
type Seconds = 'seconds' | 'second' | 'secs' | 'sec' | 's';
type Milliseconds = 'milliseconds' | 'millisecond' | 'msecs' | 'msec' | 'ms';
export type Unit =
  | Years
  | Months
  | Weeks
  | Days
  | Hours
  | Minutes
  | Seconds
  | Milliseconds;

export type UnitAnyCase = Capitalize<Unit> | Uppercase<Unit> | Unit;

export type StringValue =
  | `${number}`
  | `${number}${UnitAnyCase}`
  | `${number} ${UnitAnyCase}`;

export interface Options {
  /**
   * Set to `true` to use verbose formatting. Defaults to `false`.
   */
  long?: boolean;
  /**
   * Unit to use for conversion. Accepts any spelling and case that the
   * parser accepts, e.g. `'m'`, `'Minutes'`, `'MINS'` or `'hrs'`.
   * When formatting, the value is expressed in this unit (rounded).
   * When parsing a string without a unit, this unit is assumed.
   */
  unit?: UnitAnyCase;
}

/**
 * Parse or format the given value.
 *
 * @param value - The string or number to convert
 * @param options - Options for the conversion
 * @throws Error if `value` is not a non-empty string or a number
 */
export function ms(value: StringValue, options?: Options): number;
export function ms(value: number, options?: Options): string;
export function ms(
  value: StringValue | number,
  options?: Options,
): number | string {
  if (typeof value === 'string') {
    return parse(value, options);
  } else if (typeof value === 'number') {
    return format(value, options);
  }
  throw new Error(
    `Value provided to ms() must be a string or number. value=${JSON.stringify(value)}`,
  );
}

const unitMap: Record<string, { divisor: number; short: string; longSingular: string }> = {
  years: { divisor: y, short: 'y', longSingular: 'year' },
  year: { divisor: y, short: 'y', longSingular: 'year' },
  yrs: { divisor: y, short: 'y', longSingular: 'year' },
  yr: { divisor: y, short: 'y', longSingular: 'year' },
  y: { divisor: y, short: 'y', longSingular: 'year' },
  months: { divisor: mo, short: 'mo', longSingular: 'month' },
  month: { divisor: mo, short: 'mo', longSingular: 'month' },
  mo: { divisor: mo, short: 'mo', longSingular: 'month' },
  weeks: { divisor: w, short: 'w', longSingular: 'week' },
  week: { divisor: w, short: 'w', longSingular: 'week' },
  w: { divisor: w, short: 'w', longSingular: 'week' },
  days: { divisor: d, short: 'd', longSingular: 'day' },
  day: { divisor: d, short: 'd', longSingular: 'day' },
  d: { divisor: d, short: 'd', longSingular: 'day' },
  hours: { divisor: h, short: 'h', longSingular: 'hour' },
  hour: { divisor: h, short: 'h', longSingular: 'hour' },
  hrs: { divisor: h, short: 'h', longSingular: 'hour' },
  hr: { divisor: h, short: 'h', longSingular: 'hour' },
  h: { divisor: h, short: 'h', longSingular: 'hour' },
  minutes: { divisor: m, short: 'm', longSingular: 'minute' },
  minute: { divisor: m, short: 'm', longSingular: 'minute' },
  mins: { divisor: m, short: 'm', longSingular: 'minute' },
  min: { divisor: m, short: 'm', longSingular: 'minute' },
  m: { divisor: m, short: 'm', longSingular: 'minute' },
  seconds: { divisor: s, short: 's', longSingular: 'second' },
  second: { divisor: s, short: 's', longSingular: 'second' },
  secs: { divisor: s, short: 's', longSingular: 'second' },
  sec: { divisor: s, short: 's', longSingular: 'second' },
  s: { divisor: s, short: 's', longSingular: 'second' },
  milliseconds: { divisor: 1, short: 'ms', longSingular: 'millisecond' },
  millisecond: { divisor: 1, short: 'ms', longSingular: 'millisecond' },
  msecs: { divisor: 1, short: 'ms', longSingular: 'millisecond' },
  msec: { divisor: 1, short: 'ms', longSingular: 'millisecond' },
  ms: { divisor: 1, short: 'ms', longSingular: 'millisecond' },
};

function getUnitConfig(unit: string, caller: 'parse' | 'format') {
  const lower = unit.toLowerCase();
  const cfg = unitMap[lower];
  if (!cfg) {
    throw new Error(`Unknown unit "${unit}" provided to ms.${caller}()`);
  }
  return cfg;
}

/**
 * Parse the given string and return milliseconds.
 *
 * @param str - A string to parse to milliseconds
 * @param options - Options for the conversion
 * @returns The parsed value in milliseconds, or `NaN` if the string can't be
 * parsed
 */
export function parse(str: string, options?: Options): number {
  if (typeof str !== 'string' || str.length === 0 || str.length > 100) {
    throw new Error(
      `Value provided to ms.parse() must be a string with length between 1 and 99. value=${JSON.stringify(str)}`,
    );
  }
  const match =
    /^(?<value>-?\d*\.?\d+) *(?<unit>milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|months?|mo|years?|yrs?|y)?$/i.exec(
      str,
    );

  if (!match?.groups) {
    return NaN;
  }

  // Named capture groups need to be manually typed today.
  // https://github.com/microsoft/TypeScript/issues/32098
  const { value, unit } = match.groups as {
    value: string;
    unit: string | undefined;
  };

  const n = parseFloat(value);

  if (unit !== undefined) {
    const { divisor } = getUnitConfig(unit, 'parse');
    return n * divisor;
  }

  if (options?.unit !== undefined) {
    const { divisor } = getUnitConfig(options.unit, 'parse');
    return n * divisor;
  }

  return n;
}

/**
 * Parse the given StringValue and return milliseconds.
 *
 * @param value - A typesafe StringValue to parse to milliseconds
 * @param options - Options for the conversion
 * @returns The parsed value in milliseconds, or `NaN` if the string can't be
 * parsed
 */
export function parseStrict(value: StringValue, options?: Options): number {
  return parse(value, options);
}

/**
 * Short format for `ms`.
 */
function fmtShort(ms: number): StringValue {
  const msAbs = Math.abs(ms);
  if (msAbs >= y) {
    return `${Math.round(ms / y)}y`;
  }
  if (msAbs >= mo) {
    return `${Math.round(ms / mo)}mo`;
  }
  if (msAbs >= w) {
    return `${Math.round(ms / w)}w`;
  }
  if (msAbs >= d) {
    return `${Math.round(ms / d)}d`;
  }
  if (msAbs >= h) {
    return `${Math.round(ms / h)}h`;
  }
  if (msAbs >= m) {
    return `${Math.round(ms / m)}m`;
  }
  if (msAbs >= s) {
    return `${Math.round(ms / s)}s`;
  }
  return `${ms}ms`;
}

/**
 * Long format for `ms`.
 */
function fmtLong(ms: number): StringValue {
  const msAbs = Math.abs(ms);
  if (msAbs >= y) {
    return plural(ms, msAbs, y, 'year');
  }
  if (msAbs >= mo) {
    return plural(ms, msAbs, mo, 'month');
  }
  if (msAbs >= w) {
    return plural(ms, msAbs, w, 'week');
  }
  if (msAbs >= d) {
    return plural(ms, msAbs, d, 'day');
  }
  if (msAbs >= h) {
    return plural(ms, msAbs, h, 'hour');
  }
  if (msAbs >= m) {
    return plural(ms, msAbs, m, 'minute');
  }
  if (msAbs >= s) {
    return plural(ms, msAbs, s, 'second');
  }
  return `${ms} ms`;
}

/**
 * Format the given integer as a string.
 *
 * @param ms - milliseconds
 * @param options - Options for the conversion
 * @returns The formatted string
 */
export function format(ms: number, options?: Options): string {
  if (typeof ms !== 'number' || !Number.isFinite(ms)) {
    throw new Error('Value provided to ms.format() must be of type number.');
  }

  if (options?.unit !== undefined) {
    const cfg = getUnitConfig(options.unit, 'format');
    const rounded = Math.round(ms / cfg.divisor);
    if (options.long) {
      if (cfg.short === 'ms') {
        return `${rounded} ms`;
      }
      const pluralMs = rounded * cfg.divisor;
      return plural(pluralMs, Math.abs(pluralMs), cfg.divisor, cfg.longSingular);
    }
    return `${rounded}${cfg.short}`;
  }

  return options?.long ? fmtLong(ms) : fmtShort(ms);
}

/**
 * Pluralization helper.
 */
function plural(
  ms: number,
  msAbs: number,
  n: number,
  name: string,
): StringValue {
  const isPlural = msAbs >= n * 1.5;
  return `${Math.round(ms / n)} ${name}${isPlural ? 's' : ''}` as StringValue;
}

